// The specification bundle in docs/spec/ is the single source of the factory kit and the agent guidance.
// Tools look for some files in fixed places; this script writes those files as references into docs/spec,
// and fails in CI when they have drifted.
//
//   node .github/scripts/sync-references.mjs            write the references
//   node .github/scripts/sync-references.mjs --check    exit 1 when a reference is missing, stale or extra
//   --root <dir>                                        repository root to work on (default: current directory)
//
// What it writes:
//   .claude/agents/<name>.md        front matter of docs/spec/factory/.claude/agents/<name>.md + a pointer to it
//                                   (Claude Code reads tools, model, isolation and skills from the front matter)
//   .claude/skills/<name>/SKILL.md  front matter of docs/spec/agents/skills/<name>/SKILL.md + a pointer to it
//   .agents/skills/<name>/SKILL.md  the same, for tools that read the tool-neutral location
//   verbatim copies, only where the format has no include and the tool reads one fixed path:
//     .claude/settings.json, .claude/commands/factory-run.md, .github/pull_request_template.md, .github/ISSUE_TEMPLATE/{ticket,epic}.yml
//
// Everything else (the gate scripts, the policy, prompts, schemas) is used in place by the workflows.
// Node 22+, no dependencies.
import { readdirSync, readFileSync, writeFileSync, mkdirSync, rmSync, existsSync } from 'node:fs';
import path from 'node:path';

const SPEC = 'docs/spec';
const KIT = `${SPEC}/factory`;
const SKILLS = `${SPEC}/agents/skills`;
const GENERATOR = '.github/scripts/sync-references.mjs';

const VERBATIM = {
  '.claude/settings.json': `${KIT}/.claude/settings.json`,
  '.claude/commands/factory-run.md': `${KIT}/.claude/commands/factory-run.md`,
  '.github/pull_request_template.md': `${KIT}/.github/pull_request_template.md`,
  '.github/ISSUE_TEMPLATE/ticket.yml': `${KIT}/.github/ISSUE_TEMPLATE/ticket.yml`,
  '.github/ISSUE_TEMPLATE/epic.yml': `${KIT}/.github/ISSUE_TEMPLATE/epic.yml`,
};

// Directories whose whole content this script owns: anything in them it did not generate is stale.
const OWNED_DIRS = ['.claude/agents', '.claude/skills', '.agents/skills'];

const lf = (text) => text.replaceAll('\r\n', '\n');

export function frontMatter(text, file) {
  const t = lf(text);
  if (!t.startsWith('---\n')) throw new Error(`${file}: no front matter`);
  const end = t.indexOf('\n---\n', 4);
  if (end < 0) throw new Error(`${file}: front matter is not closed`);
  return t.slice(0, end + 5);
}

function agentStub(source, text) {
  return `${frontMatter(text, source)}
<!-- Generated by ${GENERATOR} from ${source}. Do not edit: change the source and re-run the script. -->

Your role definition is \`${source}\`. Read that file now, in full, and follow everything below its front matter as your instructions.

Paths in it are written for the installed layout (\`.github/factory/\`, \`specs/0000-framework/\`, \`adr/\`, …); resolve them through the path map in \`AGENTS.md\`.
`;
}

function skillStub(source, dir, text) {
  return `${frontMatter(text, source)}
<!-- Generated by ${GENERATOR} from ${source}. Do not edit: change the source and re-run the script. -->

This skill lives in \`${dir}/\`. Read \`${source}\` now, in full, and follow it. The files it names under \`references/\` are in \`${dir}/references/\`.

Paths in it are written for the installed layout (\`.github/factory/\`, \`specs/0000-framework/\`, \`adr/\`, …); resolve them through the path map in \`AGENTS.md\`.
`;
}

/** → Map<repo-relative path, expected content (LF)> */
export function expected(root) {
  const out = new Map();
  const read = (p) => lf(readFileSync(path.join(root, p), 'utf8'));

  const agentsDir = `${KIT}/.claude/agents`;
  for (const f of readdirSync(path.join(root, agentsDir)).filter((f) => f.endsWith('.md')).sort()) {
    const source = `${agentsDir}/${f}`;
    out.set(`.claude/agents/${f}`, agentStub(source, read(source)));
  }

  for (const e of readdirSync(path.join(root, SKILLS), { withFileTypes: true }).filter((e) => e.isDirectory()).sort((a, b) => a.name.localeCompare(b.name))) {
    const dir = `${SKILLS}/${e.name}`;
    const source = `${dir}/SKILL.md`;
    if (!existsSync(path.join(root, source))) continue;
    const stub = skillStub(source, dir, read(source));
    out.set(`.claude/skills/${e.name}/SKILL.md`, stub);
    out.set(`.agents/skills/${e.name}/SKILL.md`, stub);
  }

  for (const [target, source] of Object.entries(VERBATIM)) out.set(target, read(source));
  return out;
}

function listFiles(root, dir) {
  const full = path.join(root, dir);
  if (!existsSync(full)) return [];
  return readdirSync(full, { withFileTypes: true }).flatMap((e) => {
    const rel = `${dir}/${e.name}`;
    return e.isDirectory() ? listFiles(root, rel) : [rel];
  });
}

/** → { missing, changed, extra } repo-relative paths */
export function compare(root) {
  const want = expected(root);
  const missing = [];
  const changed = [];
  for (const [p, content] of want) {
    const full = path.join(root, p);
    if (!existsSync(full)) missing.push(p);
    else if (lf(readFileSync(full, 'utf8')) !== content) changed.push(p);
  }
  const extra = OWNED_DIRS.flatMap((d) => listFiles(root, d)).filter((p) => !want.has(p)).sort();
  return { want, missing, changed, extra };
}

if (process.argv[1]?.endsWith('sync-references.mjs')) {
  const args = process.argv.slice(2);
  const root = args.includes('--root') ? args[args.indexOf('--root') + 1] : '.';
  const { want, missing, changed, extra } = compare(root);
  const total = missing.length + changed.length + extra.length;
  if (args.includes('--check')) {
    if (total === 0) {
      console.log(`${want.size} reference(s) to ${SPEC}/ are in step`);
      process.exit(0);
    }
    for (const f of missing) console.error(`missing: ${f}`);
    for (const f of changed) console.error(`differs from its source: ${f}`);
    for (const f of extra) console.error(`not generated from ${SPEC}/: ${f}`);
    console.error(`Run: node ${GENERATOR}`);
    process.exit(1);
  }
  for (const f of [...missing, ...changed]) {
    mkdirSync(path.dirname(path.join(root, f)), { recursive: true });
    writeFileSync(path.join(root, f), want.get(f));
  }
  for (const f of extra) rmSync(path.join(root, f));
  console.log(`wrote ${missing.length + changed.length} reference(s), removed ${extra.length}`);
}
